115	            var (columns, parameters, values) = GetQueryParts(
116	                columnNames,
117	                records[recordIndex],
118	                recordIndex);
119	
120	            builder.AppendLine($"INSERT{replacePlaceholder} INTO {tableName} ({string.Join(", ", columns)})");
121	            builder.AppendLine($"VALUES ({string.Join(", ", parameters)})");
122	            builder.AppendLine($"RETURNING {rowIdentifier};");
123	
124	            for (var i = 0; i < parameters.Count; i++)
125	            {
