public class SqliteVectorStore : IVectorStore
{
    /// <summary>The connection string for the SQLite database represented by this <see cref="SqliteVectorStore"/>.</summary>
    private readonly string? _connectionString;

    /// <summary><see cref="DbConnection"/> that will be used to manage the data in SQLite when one is provided directly.</summary>
    private readonly DbConnection? _connection;

