    /// <summary>
    /// Initializes a new instance of the <see cref="SqliteVectorStore"/> class.
    /// </summary>
    /// <param name="connectionString">The connection string for the SQLite database represented by this <see cref="SqliteVectorStore"/>.</param>
    /// <param name="options">Optional configuration options for this class.</param>
    /// <remarks>
    /// The <see cref="SqliteVectorStore"/> manages the lifecycle of the SQLite connections it creates from the provided <paramref name="connectionString"/>.
    /// </remarks>
    public SqliteVectorStore(
        string connectionString,
        SqliteVectorStoreOptions? options = default)
    {
        Verify.NotNull(connectionString);

        this._connectionString = connectionString;
        this._options = options ?? new();
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="SqliteVectorStore"/> class.
    /// </summary>
    /// <param name="connection"><see cref="DbConnection"/> that will be used to manage the data in SQLite.</param>
    /// <param name="options">Optional configuration options for this class.</param>
    [Obsolete("Use the constructor that accepts a connection string instead. The library will manage the connection lifecycle internally.")]
    public SqliteVectorStore(
        DbConnection connection,
        SqliteVectorStoreOptions? options = default)
    {
        Verify.NotNull(connection);

        this._connection = connection;
        this._connectionString = connection.ConnectionString;
        this._options = options ?? new();
    }

    /// <inheritdoc />
    public virtual IVectorStoreRecordCollection<TKey, TRecord> GetCollection<TKey, TRecord>(string name, VectorStoreRecordDefinition? vectorStoreRecordDefinition = null)
        where TKey : notnull
    {
#pragma warning disable CS0618 // ISqliteVectorStoreRecordCollectionFactory is obsolete
        if (this._options.VectorStoreCollectionFactory is not null)
        {
            return this._options.VectorStoreCollectionFactory.CreateVectorStoreRecordCollection<TKey, TRecord>(
                this._connection ?? new SqliteConnection(this._connectionString),
                name,
                vectorStoreRecordDefinition);
        }
#pragma warning restore CS0618

        if (typeof(TKey) != typeof(string) && typeof(TKey) != typeof(ulong))
        {
            throw new NotSupportedException($"Only {nameof(String)} and {nameof(UInt64)} keys are supported.");
        }

        var collectionOptions = new SqliteVectorStoreRecordCollectionOptions<TRecord>
        {
            VectorStoreRecordDefinition = vectorStoreRecordDefinition,
            VectorSearchExtensionName = this._options.VectorSearchExtensionName,
            VectorVirtualTableName = this._options.VectorVirtualTableName
        };

#pragma warning disable CS0618 // The DbConnection based constructor is obsolete
        var recordCollection = (this._connection is not null
            ? new SqliteVectorStoreRecordCollection<TRecord>(this._connection, name, collectionOptions)
            : new SqliteVectorStoreRecordCollection<TRecord>(this._connectionString!, name, collectionOptions))
            as IVectorStoreRecordCollection<TKey, TRecord>;
#pragma warning restore CS0618

        return recordCollection!;
    }

